(7693135, 1260480, 4008, '<td valign="top">Beautiful scene. Nice softness as result of the long exposure and nice balanced light and tones. I would have cloned out the warning sign on the rock and the green plastic container.</td>', 'Beautiful scene. Nice softness as result of the long exposure and nice balanced light and tones. I would have cloned out the warning sign on the rock and the green plastic container.', '2021-05-01 12:36:36.000000', NULL, 1),
(7693136, 1261082, 4008, '<td valign="top">Love it. Nice soft colours and textures. I find the thin diagonal wires distracting and would have cloned them out.</td>', 'Love it. Nice soft colours and textures. I find the thin diagonal wires distracting and would have cloned them out.', '2021-05-01 12:41:50.000000', NULL, 1),
(7693139, 1261195, 4008, '<td valign="top">Love the blue tones and the backlight of the sun. A pity the top of her hair is blown out.</td>', 'Love the blue tones and the backlight of the sun. A pity the top of her hair is blown out.', '2021-05-01 12:48:55.000000', NULL, 1),
(7693140, 1260620, 124815, '<td valign="top">Great expression!</td>', 'Great expression!', '2021-05-01 12:49:45.000000', NULL, 1),
